/* ============================================================
   INIT — birlashtirish va FIXES qo'llash
   ============================================================ */
D = D.concat(N, N2);
TL = TL.concat(TL2.filter(function(t){return !TL.some(function(x){return x.id===t.id})}));

(function applyFixes(){
  var all = D.concat(FW, TL);
  Object.keys(FIXES).forEach(function(id){
    var d = all.filter(function(x){return x.id===id})[0];
    if(!d) return;
    Object.keys(FIXES[id]).forEach(function(k){
      if(k==="sites"){ if(TLUI[id]) TLUI[id][2] = FIXES[id][k]; }
      else d[k] = FIXES[id][k];
    });
  });
})();

var TYPEOVR = {garmin:"Ransomware"};
function yearOf(s){var m=/\d{4}/.exec(String(s||""));return m?+m[0]:null}
D.forEach(function(d){if(TYPEOVR[d.id])d.t=TYPEOVR[d.id];d.y=parseInt(d.yr,10)||yearOf(d.yr)||0;d.key=d.k||d.n.split(" ")[0];d.chk=d.chk||"2026-11-08"});
FW.forEach(function(d){d.y=yearOf(d.yr)||0;d.chk=d.chk||"2026-11-08"});
TL.forEach(function(d){d.y=yearOf(d.yr)||0;d.logo=LOGOS[d.id]||null;d.chk=d.chk||"2026-11-08"});
CRYPT.forEach(function(d){d.y=yearOf(d.yr)||0});
FUND.forEach(function(d){d.y=yearOf(d.yr)||0});
STD.forEach(function(d){d.y=yearOf(d.yr)||0});

